<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {page} from '$app/state';import {listings,orders} from '$lib/api';import type {Listing} from '$lib/types';let item=$state<Listing|null>(null),qty=$state(1),error=$state('');$effect(()=>{listings.one(page.params.id || "").then(v=>item=v).catch(e=>error=e.message)});async function order(){if(!item)return;await orders.create(item.id,qty);alert('Order created — invoice pending')}</script><PageShell eyebrow="LISTING DETAIL" title={item?.title||'Loading listing…'}>{#if error}<p class="alert">{error}</p>{:else if item}<div class="detail-grid"><div class="detail-art">♻</div><div class="form-card"><p class="muted">{item.producerName} · {item.location}</p><p>{item.description||'Fresh organic material, ready for collection.'}</p><label>Quantity ({item.unit})<input type="number" min="1" bind:value={qty}/></label><h2>{(qty*item.priceSats).toLocaleString()} sats</h2><button class="btn primary" onclick={order}>Create Lightning invoice ↗</button></div></div>{/if}</PageShell>
